/**
 * `repr()` for the value graph bencoder returns: int, bytes, list, dict.
 *
 * `print(value)` uses `str(value)`, and for every one of these types
 * `str is repr` (containers always repr their members), so a single
 * implementation covers both.
 */

import { Bytes } from './bytestring.mjs';
import { PyDict } from './pydict.mjs';
import { pyIntRepr } from './pyint.mjs';

/**
 * `repr(bytes)`, following CPython's `bytes_repr`:
 *   * the literal is single-quoted unless it contains `'` and no `"`,
 *   * the active quote and backslash are backslash-escaped,
 *   * tab / newline / carriage return get their short escapes,
 *   * every other byte outside the printable ASCII range becomes `\xNN`.
 */
export function pyBytesRepr(value) {
  const raw = value.raw;
  const quote = raw.includes("'") && !raw.includes('"') ? '"' : "'";

  let body = '';
  for (let index = 0; index < raw.length; index += 1) {
    const ch = raw[index];
    const code = raw.charCodeAt(index);
    if (ch === quote || ch === '\\') body += `\\${ch}`;
    else if (code === 0x09) body += '\\t';
    else if (code === 0x0a) body += '\\n';
    else if (code === 0x0d) body += '\\r';
    else if (code < 0x20 || code >= 0x7f) body += `\\x${code.toString(16).padStart(2, '0')}`;
    else body += ch;
  }
  return `b${quote}${body}${quote}`;
}

export function pyRepr(value) {
  if (typeof value === 'bigint') return pyIntRepr(value);
  if (value instanceof Bytes) return pyBytesRepr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof PyDict) {
    const body = value
      .entries()
      .map(([key, item]) => `${pyRepr(key)}: ${pyRepr(item)}`)
      .join(', ');
    return `{${body}}`;
  }
  return String(value);
}

/** `str(value)` — identical to `repr` for every type reachable here. */
export const pyStr = pyRepr;
